import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE="# External reference: statistics page /practice/28274/\n# Accepted submission: 52504766\n# Source: http://cs101.openjudge.cn/practice/solution/52504766/\n# License: not declared on the submission page; no license is inferred.\n\nfrom collections import deque\n\nn, m = map(int, input().split())\nmat = [list(input()) for _ in range(n)]\n\ncnt = 0\ndirs = [(0,1), (0,-1), (-1,0), (1,0)]\n\nfor i in range(n):\n    for j in range(m):\n        if mat[i][j] != '0':\n            cnt += 1\n            q = deque()\n            q.append((i, j))\n            mat[i][j] = '0'\n\n            while q:\n                x, y = q.popleft()\n                for dx, dy in dirs:\n                    nx, ny = x + dx, y + dy\n                    if 0 <= nx < n and 0 <= ny < m:\n                        if mat[nx][ny] != '0':\n                            mat[nx][ny] = '0'\n                            q.append((nx, ny))\n\nprint(cnt)"
SAMPLE='4 10\n0234500067\n1034560500\n2045600671\n0000000089\n'
EXTRA_CASE='400 400\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n'
GENERATOR_NAME='g28274'
def g28274(r):
    n, m = r.randint(1, 30), r.randint(1, 30)
    return f"{n} {m}\n" + "\n".join("".join(r.choice("0123456789") for _ in range(m)) for _ in range(n)) + "\n"

def run(text):
    with tempfile.TemporaryDirectory(prefix='producecase-') as d:
        p=Path(d)/'main.py'; p.write_text(REFERENCE)
        x=subprocess.run([sys.executable,str(p)],input=text,text=True,capture_output=True,timeout=90)
        if x.returncode: raise SystemExit(x.stderr)
        return x.stdout
def scale_case(): return EXTRA_CASE
def main():
    d=Path('data'); d.mkdir(exist_ok=True)
    extra=scale_case(); cases=[SAMPLE]+([extra] if extra else [])+[globals()[GENERATOR_NAME](random.Random(s)) for s in range(1,21)]
    for i,c in enumerate(cases): (d/f'{i}.in').write_text(c); (d/f'{i}.out').write_text(run(c))
if __name__=='__main__': main()
